package com.dogmania.api.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Slf4j
@Service
public class AuditService {

    /** Durable product audit is generated by the PostgreSQL trigger, inside the CRUD transaction.
     * The runtime role deliberately has no INSERT permission on audit_logs. Application logs
     * add the authenticated actor and login events; forward these to restricted log storage.
     */
    public void logAction(String action, String entityType, UUID entityId, String performedBy, String details) {
        log.info("audit action={} entity={} id={} actor={}", action, entityType, entityId,
                performedBy == null ? "unknown" : performedBy.replaceAll("[\\r\\n\\t]", "_"));
    }
}
